WITH f AS (SELECT * FROM facility_terms), p AS (SELECT * FROM period_cases), c AS (SELECT * FROM collateral_cases), pr AS (SELECT * FROM purchase_sizes), x AS (SELECT c.scenario, p.period, p.seasonal, pr.proposal, pr.purchase_cost AS xcost, (c.credit_card_receivables+c.pharmacy_receivables)*f.receivable_rate AS a, c.script_liquidation_value*f.script_rate AS s, (c.regular_inventory_cost+c.regular_purchase_fraction*pr.purchase_cost)*c.regular_appraisal*CASE WHEN p.seasonal=1 THEN f.seasonal_inventory_rate ELSE f.ordinary_inventory_rate END AS r, (c.perishable_inventory_cost+(1.0-c.regular_purchase_fraction)*pr.purchase_cost)*c.perishable_appraisal*CASE WHEN p.seasonal=1 THEN f.seasonal_inventory_rate ELSE f.ordinary_inventory_rate END AS pv, c.availability_reserves AS res, f.commitment, f.shared_dollar_cap, c.loans, c.letters_of_credit FROM c CROSS JOIN p CROSS JOIN pr CROSS JOIN f), y AS (SELECT x.*, CASE WHEN a+r+pv-res<3.0*s THEN (a+r+pv-res)/3.0 ELSE (a+r+pv-res+s)/4.0 END AS craw, MIN(pv,(a+r+s-res)/3.0) AS q FROM x), z AS (SELECT y.*, MIN(shared_dollar_cap,craw) AS cs FROM y), b AS (SELECT z.*, a+r-res+MIN(s,cs)+q AS bb FROM z) SELECT scenario, period, proposal, bb AS borrowing_base_usd_million, (loans+letters_of_credit+xcost) AS revolving_exposure_usd_million, (MIN(commitment,bb)-(loans+letters_of_credit+xcost)) AS funding_surplus_usd_million, CASE WHEN MIN(commitment,bb) >= (loans+letters_of_credit+xcost) THEN 1 ELSE 0 END AS feasible FROM b;
